import type { Meta, StoryObj } from "@storybook/vue3";
import { KozmosCodeBlock } from "../../index";

/**
 * Vue's CodeBlock: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port CodeBlock`; Default and Scroll drawn by hand.
 */
type Args = Record<string, unknown>;

// Every story React's has draws with its own render, so this one does too.
const meta: Meta<Args> = {
  title: "Vue/Core/Data display/CodeBlock",
  component: KozmosCodeBlock,
  parameters: { layout: "padded" },
};

export default meta;
type Story = StoryObj<Args>;

const MERGED_UNIT = `{
  "mergedUnit": {
    "fid": "f-1209",
    "name": "Bean & Leaf Café",
    "sources": ["f-1042", "f-1043"],
    "mergedAt": "2026-10-29T09:41:00Z",
    "geometry": { "type": "Polygon", "levels": [1] }
  }
}`;

/**
 * React's Default, MAP-619's merged unit (GAP-216, decision 225): a custom
 * field's JSON, read-only, wrapping its long lines, with a copy that says
 * it copied.
 */
export const Default: Story = {
  render: () => ({
    components: { KozmosCodeBlock },
    setup: () => ({ code: MERGED_UNIT }),
    template: `
      <div style="max-width: 480px">
        <KozmosCodeBlock label="mergedUnit JSON" :code="code" copyable />
      </div>
    `,
  }),
};

/**
 * React's Scroll: with `:wrap="false"` each line stays whole and the block
 * scrolls sideways; the scroller is a stop on the keyboard's way.
 */
export const Scroll: Story = {
  render: () => ({
    components: { KozmosCodeBlock },
    setup: () => ({ code: MERGED_UNIT }),
    template: `
      <div style="max-width: 320px">
        <KozmosCodeBlock label="mergedUnit JSON" :code="code" :wrap="false" />
      </div>
    `,
  }),
};
